<template><section><div class="mb-6"><h1 class="text-2xl font-bold">{{t('backup.title')}}</h1><p class="mt-1 text-sm text-slate-500">{{t('backup.description')}}</p></div><div class="card flex flex-wrap items-center gap-3"><button class="btn-primary" @click="download">{{t('backup.export')}}</button><label class="btn-ghost cursor-pointer">{{t('backup.import')}}<input class="hidden" type="file" accept="application/json" @change="importFile"/></label><span v-if="message" class="text-sm text-emerald-300">{{message}}</span><span v-if="error" class="text-sm text-red-300">{{error}}</span></div></section></template>
<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';const{t}=useI18n(),message=ref(''),error=ref('');async function download(){const d=await api.get<any>('/backup/export');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`3xui-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}async function importFile(e:any){error.value='';message.value='';try{const f=e.target.files?.[0];if(!f)return;const d=JSON.parse(await f.text());const r=await api.post<any>('/backup/import',d);message.value=`Imported ${r.imported} records`}catch(x){error.value=(x as Error).message||t('backup.invalid')}} </script>
